std::uint8_t k = static_cast<std::uint8_t>(bloom_filter.data()[0]);
if (k == 0 || bloom_filter.size() < 2) {
    return false;
}
const char* bits = bloom_filter.data() + 1;
std::size_t bits_len = bloom_filter.size() - 1;  // in bytes
if (bits_len == 0) {
    return false;
}

// hash the key (portable, matches typical LevelDB usage)
std::uint32_t h = static_cast<std::uint32_t>(
    std::hash<std::string_view>{}(std::string_view(key.data(), key.size())));

// compute delta for subsequent probes
std::uint32_t delta = (h >> 17) | (h << 15);

for (std::uint32_t i = 0; i < k; ++i) {
    std::uint32_t bitpos = (h + i * delta) % (static_cast<std::uint32_t>(bits_len) * 8);
    std::size_t byte_index = bitpos / 8;
    std::uint8_t mask = static_cast<std::uint8_t>(1U << (bitpos % 8));
    if ((static_cast<std::uint8_t>(bits[byte_index]) & mask) == 0) {
        return false;
    }
}
return true;

